//! cad_brep.rs: a cad-brep buffer (one part's B-rep) for Rust readers. Generated by
//! packages/cad-brep/gen/rust.ts from packages/cad-brep/src/layout.ts, which documents every table and column;
//! don't edit. The buffer: the magic, a u32 column count, then per column its byte offset and element count
//! (u32 each), then the columns, each 8-byte aligned. Little-endian. `Brep::open` copies the buffer (so it
//! needn't be aligned) and checks its header; each column is then a slice of its type, by a method named for
//! its table and column (`edge_curve`).
//!
//! Curves (d the row's dim; a placement 9 reals in 3D: origin, axis, x direction; 4 in 2D: origin, x direction), from a
//! row's real and int offsets into its table's pools:
//!   line: reals point (d), unit direction (d), magnitude (the parameter is distance / magnitude); ints none.
//!   circle: reals placement, radius; ints none.
//!   ellipse: reals placement, semi_axis_1 (along x), semi_axis_2; ints none.
//!   hyperbola: reals placement, semi_axis, semi_imag_axis; ints none.
//!   parabola: reals placement, focal_dist; ints none.
//!   bspline: reals knots (k, distinct, increasing), poles (n x d), weights (n, if rational); ints degree, n, k,
//!   rational (0/1), closed (LOGICAL), self_intersect (LOGICAL), form (CURVE_FORMS), multiplicities (k).
//!   polyline: reals points (n x d); ints n.
//!   trimmed: reals trim 1 parameter, trim 2 parameter (NaN if not given), trim 1 point (d), trim 2 point (d) (NaN if
//!   not given); ints basis curve, sense_agreement (0/1), master_representation (TRIM_PREFERENCES).
//!   composite: reals none; ints n, self_intersect (LOGICAL), then per segment: curve, same_sense (0/1), transition
//!   (TRANSITIONS).
//!   offset: reals distance, then for d = 3 the reference direction (3); ints basis curve, self_intersect (LOGICAL).
//!
//! Surfaces (a placement 9 reals), from a row's real and int offsets into its table's pools:
//!   plane: reals placement; ints none.
//!   cylinder: reals placement, radius; ints none.
//!   cone: reals placement, radius (at v = 0), semi_angle; ints none.
//!   sphere: reals placement, radius; ints none.
//!   torus: reals placement, major_radius, minor_radius; ints degenerate (0/1), select_outer (0/1).
//!   bspline: reals u knots (ku), v knots (kv), poles (nu x nv x 3, u-major: pole (i, j) at i * nv + j), weights (nu x
//!   nv, if rational); ints u degree, v degree, nu, nv, ku, kv, rational (0/1), u_closed, v_closed, self_intersect
//!   (LOGICAL each), form (SURFACE_FORMS), u multiplicities (ku), v multiplicities (kv).
//!   extrusion: reals unit direction (3), magnitude; ints swept curve.
//!   revolution: reals axis location (3), unit axis direction (3); ints swept curve.
//!   offset: reals distance; ints basis surface, self_intersect (LOGICAL).
//!   rectangularTrimmed: reals u1, u2, v1, v2; ints basis surface, usense (0/1), vsense (0/1).
//!   curveSwept: reals none; ints swept curve, directrix curve, reference surface.
//!   fixedReferenceSwept: reals fixed reference direction (3); ints swept curve, directrix curve.

#![allow(dead_code)]

#[cfg(not(target_endian = "little"))]
compile_error!("cad-brep buffers are little-endian");

pub const MAGIC: &[u8; 4] = b"CBR3";
pub const HEADER_BYTES: usize = 496;
pub const COLUMN_COUNT: usize = 61;

/// Each column's element type, in buffer order: b u8, i i32, u u32, f f64.
const TYPES: &[u8; COLUMN_COUNT] = b"fffifiifbbiiubiiuffuiiibbffuibifubbbiiuibiifubiiubiiuibibbiiu";

const fn bytes(k: usize) -> usize {
    match TYPES[k] {
        b'b' => 1,
        b'f' => 8,
        _ => 4,
    }
}

